import React, { useState, useEffect } from 'react';
import { Line } from 'react-chartjs-2';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend,
} from 'chart.js';

ChartJS.register(
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend
);

const DataChart = ({ logData, columns }) => {
    const [selectedPid, setSelectedPid] = useState('');
    const [pidOptions, setPidOptions] = useState([]);
    const [chartData, setChartData] = useState({ labels: [], datasets: [] });

    useEffect(() => {
        if (logData && logData.length > 0 && columns) {
            const numericCols = columns.filter(col =>
                col !== 'timestamp' && typeof logData[0][col] === 'number'
            );
            setPidOptions(numericCols);
            if (numericCols.length > 0) {
                setSelectedPid(numericCols[0]);
            }
        }
    }, [logData, columns]);

    useEffect(() => {
        if (!logData || logData.length === 0 || !selectedPid) {
            setChartData({ labels: [], datasets: [] });
            return;
        }

        const labels = logData.map(d => new Date(d.timestamp).toLocaleTimeString());
        const data = logData.map(d => d[selectedPid]);

        setChartData({
            labels,
            datasets: [
                {
                    label: selectedPid,
                    data: data,
                    borderColor: 'rgb(75, 192, 192)',
                    backgroundColor: 'rgba(75, 192, 192, 0.5)',
                    tension: 0.1,
                },
            ],
        });

    }, [logData, selectedPid]);

    const options = {
        responsive: true,
        plugins: {
            legend: {
                position: 'top',
            },
            title: {
                display: true,
                text: `Chart for ${selectedPid}`,
            },
        },
    };

    return (
        <div>
            <div style={{ marginBottom: '10px' }}>
                <label htmlFor="pid-select-chart">Select Data: </label>
                <select id="pid-select-chart" value={selectedPid} onChange={(e) => setSelectedPid(e.target.value)}>
                    {pidOptions.map(pid => <option key={pid} value={pid}>{pid}</option>)}
                </select>
            </div>
            <Line options={options} data={chartData} />
        </div>
    );
};

export default DataChart;
